import math

def check_condition(n):
    """
    Checks if k^2 === 1 (mod n) for all k such that gcd(k, n) = 1.
    """
    if n < 2:
        return False

    # We only need to check k from 1 to n-1 since the condition involves modulo n.
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check if k^2 - 1 is a multiple of n
            if (k * k - 1) % n != 0:
                # Found a counterexample
                return False
    # If the loop completes without finding a counterexample
    return True

solutions = []
for n in range(2, 31):
    if check_condition(n):
        solutions.append(n)

print(f"Solutions found in the range 2 <= n <= 30: {solutions}")

import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def check_condition(n):
    """Checks if for all k coprime to n, k^2 === 1 (mod n)."""
    if n < 2:
        return False

    # Test k from 1 up to n-1
    for k in range(1, n):
        if gcd(k, n) == 1:
            # Check k^2 - 1 is a multiple of n
            if (k*k - 1) % n != 0:
                return False
    return True

# Values to test: 2^a or 3 * 2^a in the range 31 <= n <= 100
test_values = [32, 64, 48, 96]
solutions = []

print("--- Brute Force Test Results ---")
for n in test_values:
    if check_condition(n):
        solutions.append(n)
        print(f"n = {n}: SATISFIES the condition.")
    else:
        print(f"n = {n}: FAILS the condition.")

print(f"\nSolutions found in this range and form: {solutions}")
